import { test, expect } from '@playwright/test';

test.describe('Concurrent API Calls', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should display data after multiple concurrent API calls', async ({ page }) => {
    const apiCall1 = page.waitForResponse(response => response.url().includes('/api/data1') && response.status() === 200);
    const apiCall2 = page.waitForResponse(response => response.url().includes('/api/data2') && response.status() === 200);

    await Promise.all([
      apiCall1,
      apiCall2,
      page.click(getByRole('button', { name: 'Fetch Data' }))
    ]);

    const data1 = await page.locator(getByText('Data from API 1')).innerText();
    const data2 = await page.locator(getByText('Data from API 2')).innerText();

    expect(data1).toBe('Expected Data 1');
    expect(data2).toBe('Expected Data 2');
  });

  test('should handle API errors gracefully', async ({ page }) => {
    await page.route('**/api/data1', route => route.abort('failed'));
    await page.route('**/api/data2', route => route.abort('failed'));

    await page.click(getByRole('button', { name: 'Fetch Data' }));

    const errorMessage = await page.locator(getByText('Failed to fetch data')).innerText();
    expect(errorMessage).toBe('Failed to fetch data');
  });
});
